import os
# Check HF cache for the LoRA adapter
cache_dirs = [
    os.path.expanduser('~/.cache/huggingface/hub/'),
    '/root/.cache/huggingface/hub/'
]
for d in cache_dirs:
    if os.path.exists(d):
        for entry in os.listdir(d):
            if 'xlm-roberta' in entry.lower() or 'lora' in entry.lower():
                print(f'Found in {d}: {entry}')
                full = os.path.join(d, entry)
                if os.path.isdir(full):
                    for sub in os.listdir(full):
                        print(f'  {sub}')
" 2>&1

